<?php
namespace App\Models;use App\Domain\Imports\ImportStatus;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
final class DataImport extends Model{use HasUuids,SoftDeletes;protected $table='imports';protected $guarded=[];protected function casts():array{return ['status'=>ImportStatus::class,'source_schema_json'=>'array','source_options_json'=>'array','import_policy_json'=>'array','file_size'=>'integer','detected_row_count'=>'integer','deleted_at'=>'datetime','retention_until'=>'datetime'];}public function executions(){return $this->hasMany(ImportExecution::class,'import_id');}public function mappings(){return $this->hasMany(ImportMapping::class,'import_id');}public function destinationSchema(){return $this->belongsTo(DestinationSchema::class,'destination_schema_id');}}
